이러한 개선은 사용자에게 데이터 로딩 상태에 대한 명확한 시각적 피드백을 제공하여 사용자 경험을 향상시킵니다.

데이터 로딩 및 파일 다운로드 중 발생할 수 있는 다양한 오류 상황에 대한 처리를 개선하고, 사용자에게 명확한 피드백을 제공합니다. 토스트 메시지를 활용하여 성공 및 오류 상태를 알립니다.

먼저 react-hot-toast 라이브러리를 설치합니다:

```bash
npm install react-hot-toast
# 또는
yarn add react-hot-toast
```

그리고 다음과 같이 구현합니다:

```tsx
import { Toaster, toast } from 'react-hot-toast';

// 메인 컴포넌트 내부에 Toaster 추가
<>
  <Toaster position="top-right" />
  {/* 기존 컴포넌트 */}
</>

// 데이터 로딩 에러 처리 개선
const loadData = async () => {
  setLoading(true);
  try {
    const data = await fetchWorkRecords();
    setRecords(data);
    setFilteredRecords(data);
  } catch (error) {
    console.error('데이터 로딩 오류:', error);
    toast.error('작업 이력을 불러오는 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
    // 빈 배열로 설정하여 UI가 깨지지 않도록 함
    setRecords([]);
    setFilteredRecords([]);
  } finally {
    setLoading(false);
  }
};

// 파일 다운로드 에러 처리 개선 (FileDownloadSection 컴포넌트 내부)
const handleDownload = async (file) => {
  try {
    // 다운로드 시작 알림
    const toastId = toast.loading(`${file.original_name} 다운로드 중...`);

    // Supabase Storage에서 파일 URL 가져오기
    const { data, error } = await supabase
      .storage
      .from('work_files')
      .createSignedUrl(file.storage_path, 60);

    if (error) throw error;

    // 파일 다운로드 링크 열기
    window.open(data.signedUrl, '_blank');

    // 성공 알림
    toast.success(`${file.original_name} 다운로드 시작됨`, {
      id: toastId
    });
  } catch (err) {
    console.error('파일 다운로드 오류:', err);

    // 오류 유형에 따른 맞춤형 메시지
    let errorMessage = '파일 다운로드 중 오류가 발생했습니다.';

    if (err.message?.includes('not found')) {
      errorMessage = '파일을 찾을 수 없습니다. 관리자에게 문의하세요.';
    } else if (err.message?.includes('permission')) {
      errorMessage = '파일 다운로드 권한이 없습니다.';
    } else if (err.message?.includes('network')) {
      errorMessage = '네트워크 연결을 확인해주세요.';
    }

    toast.error(errorMessage);
  }
};

// 일괄 다운로드 에러 처리 개선
const handleBulkDownload = async () => {
  if (files.length === 0) return;

  const toastId = toast.loading('파일 준비 중...');

  try {
    setLoading(true);

    const zip = new JSZip();
    const promises = [];
    let successCount = 0;
    let failCount = 0;

    // 각 파일에 대한 다운로드 Promise 생성
    for (const file of files) {
      const promise = new Promise(async (resolve, reject) => {
        try {
          // Supabase Storage에서 파일 URL 가져오기
          const { data, error } = await supabase
            .storage
            .from('work_files')
            .createSignedUrl(file.storage_path, 60);

          if (error) throw error;

          // 파일 다운로드 및 ZIP에 추가
          const response = await fetch(data.signedUrl);
          if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

          const blob = await response.blob();
          zip.file(file.original_name, blob);
          successCount++;
          resolve();
        } catch (err) {
          console.error(`파일 '${file.original_name}' 다운로드 오류:`, err);
          failCount++;
          // 개별 파일 오류는 전체 프로세스를 중단하지 않음
          resolve();
        }
      });

      promises.push(promise);
    }

    // 진행 상태 업데이트
    toast.loading(`파일 다운로드 중... (0/${files.length})`, { id: toastId });

    // 모든 파일 다운로드 완료 대기
    await Promise.all(promises);

    if (successCount === 0) {
      throw new Error('다운로드할 수 있는 파일이 없습니다.');
    }

    // ZIP 파일 생성 및 다운로드
    toast.loading(`ZIP 파일 생성 중...`, { id: toastId });
    const content = await zip.generateAsync({ type: 'blob' });
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    saveAs(content, `work-files-${recordId}-${timestamp}.zip`);

    // 결과 알림
    if (failCount > 0) {
      toast.success(`ZIP 파일 생성 완료 (${successCount}개 성공, ${failCount}개 실패)`, { id: toastId });
    } else {
      toast.success('모든 파일이 ZIP으로 다운로드되었습니다.', { id: toastId });
    }
  } catch (err) {
    console.error('일괄 다운로드 오류:', err);
    toast.error(err.message || '파일 일괄 다운로드 중 오류가 발생했습니다.', { id: toastId });
  } finally {
    setLoading(false);
  }
};
```

