// hooks/useWorkRecords.ts
import { useQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabaseClient';

export const useWorkRecords = (page = 0, pageSize = 10) => {
  return useQuery({
    queryKey: ['workRecords', page, pageSize],
    queryFn: async () => {
      const { data, error, count } = await supabase
        .from('work_records')
        .select('*', { count: 'exact' })
        .range(page * pageSize, (page + 1) * pageSize - 1);

      if (error) throw error;
      return { records: data as WorkRecord[], totalCount: count };
    },
    keepPreviousData: true
  });
};

