```tsx
// hooks/useFileDownload.ts
import { useState } from 'react';
import { supabase } from '../lib/supabaseClient';

export const useFileDownload = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const downloadFile = async (path: string, fileName: string) => {
    try {
      setIsLoading(true);
      setError(null);

      const { data, error } = await supabase.storage
        .from('work_files')
        .download(path);

      if (error) throw error;

      // 파일 다운로드 처리
      const url = URL.createObjectURL(data);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      URL.revokeObjectURL(url);
      document.body.removeChild(a);

      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : '파일 다운로드 중 오류가 발생했습니다.');
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  return { downloadFile, isLoading, error };
};

// components/FileDownloadList/index.tsx
import { useState } from 'react';
import { useFileDownload } from '../../hooks/useFileDownload';
import { ArrowDownTrayIcon } from '@heroicons/react/24/outline';

interface FileDownloadListProps {
  files: string[];
  recordId: string;
}

const FileDownloadList = ({ files, recordId }: FileDownloadListProps) => {
  const { downloadFile, isLoading, error } = useFileDownload();
  const [downloadingIndex, setDownloadingIndex] = useState<number | null>(null);

  const handleDownload = async (file: string, index: number) => {
    setDownloadingIndex(index);
    await downloadFile(`${recordId}/${file}`, file);
    setDownloadingIndex(null);
  };

  const handleDownloadAll = async () => {
    // ZIP 파일 다운로드 로직 구현 (백엔드 API 호출 필요)
  };

  if (files.length === 0) {
    return <p className="text-gray-500">등록된 파일이 없습니다.</p>;
  }

  return (
    <div>
      {error && <p className="text-red-500 mb-2">{error}</p>}

      <div className="flex justify-between items-center mb-3">
        <h4 className="font-medium">파일 목록 ({files.length}개)</h4>
        {files.length > 1 && (
          <button
            onClick={handleDownloadAll}
            disabled={isLoading}
            className="px-3 py-1 bg-blue-50 text-blue-600 rounded-md text-sm hover:bg-blue-100 flex items-center"
          >
            <ArrowDownTrayIcon className="h-4 w-4 mr-1" />
            전체 다운로드
          </button>
        )}
      </div>

      <ul className="space-y-2">
        {files.map((file, index) => (
          <li key={index} className="flex justify-between items-center p-2 bg-gray-50 rounded-md">
            <span className="truncate">{file}</span>
            <button
              onClick={() => handleDownload(file, index)}
              disabled={isLoading}
              className="text-blue-600 hover:text-blue-800"
            >
              {downloadingIndex === index ? '다운로드 중...' : '다운로드'}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};
```

작업 기록과 관련된 여러 파일을 ZIP 형식으로 압축하여 일괄 다운로드하는 기능을 구현합니다. 클라이언트 측에서 JSZip 라이브러리를 사용하여 파일을 압축하거나, 서버리스 함수를 통해 서버 측에서 압축 처리를 수행합니다.

```tsx
// hooks/useZipDownload.ts
import { useState } from 'react';
import { supabase } from '../lib/supabaseClient';
import JSZip from 'jszip';

export const useZipDownload = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const downloadFilesAsZip = async (recordId: string, files: string[], zipFileName: string) => {
    try {
      setIsLoading(true);
      setError(null);
      setProgress(0);

      const zip = new JSZip();
      let completedFiles = 0;

      // 각 파일을 다운로드하여 ZIP에 추가
      for (const file of files) {
        const { data, error } = await supabase.storage
          .from('work_files')
          .download(`${recordId}/${file}`);

        if (error) throw error;

        zip.file(file, data);
        completedFiles++;
        setProgress(Math.round((completedFiles / files.length) * 100));
      }

      // ZIP 파일 생성 및 다운로드
      const content = await zip.generateAsync({ 
        type: 'blob',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 }
      }, (metadata) => {
        setProgress(Math.round(metadata.percent));
      });

      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = zipFileName || `작업파일_${recordId}.zip`;
      document.body.appendChild(a);
      a.click();
      URL.revokeObjectURL(url);
      document.body.removeChild(a);

      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : '파일 다운로드 중 오류가 발생했습니다.');
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  return { downloadFilesAsZip, isLoading, progress, error };
};

