```tsx
// components/WorkRecordTable/index.tsx
import { useState, useMemo } from 'react'
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  ColumnDef,
  SortingState,
  FilterFn
} from '@tanstack/react-table'
import { WorkRecord } from '../../types/workRecord'
import { ChevronUpIcon, ChevronDownIcon, FunnelIcon } from '@heroicons/react/24/outline'

interface WorkRecordTableProps {
  data: WorkRecord[];
  isLoading: boolean;
  onRowClick: (record: WorkRecord) => void;
}

const WorkRecordTable = ({ data, isLoading, onRowClick }: WorkRecordTableProps) => {
  const [sorting, setSorting] = useState<SortingState>([]);
  const [filters, setFilters] = useState<Record<string, any>>({});
  const [filterOpen, setFilterOpen] = useState(false);

  const columns = useMemo<ColumnDef<WorkRecord>[]>(
    () => [
      {
        accessorKey: 'created_at',
        header: ({ column }) => (
          <div className="flex items-center cursor-pointer" onClick={() => column.toggleSorting()}>
            작업일
            {column.getIsSorted() === 'asc' ? (
              <ChevronUpIcon className="ml-1 h-4 w-4" />
            ) : column.getIsSorted() === 'desc' ? (
              <ChevronDownIcon className="ml-1 h-4 w-4" />
            ) : null}
          </div>
        ),
        cell: ({ row }) => new Date(row.original.created_at).toLocaleDateString('ko-KR'),
        filterFn: 'dateRange' as any,
      },
      {
        accessorKey: 'customer',
        header: ({ column }) => (
          <div className="flex items-center cursor-pointer" onClick={() => column.toggleSorting()}>
            고객/장비
            {column.getIsSorted() === 'asc' ? (
              <ChevronUpIcon className="ml-1 h-4 w-4" />
            ) : column.getIsSorted() === 'desc' ? (
              <ChevronDownIcon className="ml-1 h-4 w-4" />
            ) : null}
          </div>
        ),
        cell: ({ row }) => `${row.original.customer} / ${row.original.equipment}`,
        filterFn: 'includesString' as any,
      },
      // 나머지 컬럼 정의...
    ],
    []
  );

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      globalFilter: filters,
    },
    onSortingChange: setSorting,
    onGlobalFilterChange: setFilters,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    filterFns: {
      dateRange: (row, columnId, filterValue) => {
        if (!filterValue || !filterValue.start || !filterValue.end) return true;
        const cellValue = new Date(row.getValue(columnId));
        return cellValue >= new Date(filterValue.start) && cellValue <= new Date(filterValue.end);
      },
      includesString: (row, columnId, filterValue) => {
        if (!filterValue) return true;
        const cellValue = String(row.getValue(columnId)).toLowerCase();
        return cellValue.includes(filterValue.toLowerCase());
      },
    },
  });

  return (
    <div>
      <div className="mb-4 flex justify-between items-center">
        <h2 className="text-xl font-semibold">작업 이력</h2>
        <button
          onClick={() => setFilterOpen(!filterOpen)}
          className="px-3 py-1 bg-gray-100 rounded-md flex items-center text-sm"
        >
          <FunnelIcon className="h-4 w-4 mr-1" />
          필터
        </button>
      </div>

      {filterOpen && (
        <div className="mb-4 p-4 bg-gray-50 rounded-lg">
          <h3 className="font-medium mb-2">필터 옵션</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">작업일</label>
              <div className="flex space-x-2">
                <input
                  type="date"
                  className="px-2 py-1 border rounded-md text-sm w-full"
                  onChange={(e) => {
                    const newFilters = { ...filters };
                    if (!newFilters.created_at) newFilters.created_at = {};
                    newFilters.created_at.start = e.target.value;
                    setFilters(newFilters);
                  }}
                />
                <input
                  type="date"
                  className="px-2 py-1 border rounded-md text-sm w-full"
                  onChange={(e) => {
                    const newFilters = { ...filters };
                    if (!newFilters.created_at) newFilters.created_at = {};
                    newFilters.created_at.end = e.target.value;
                    setFilters(newFilters);
                  }}
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">고객/장비</label>
              <input
                type="text"
                className="px-2 py-1 border rounded-md text-sm w-full"
                onChange={(e) => {
                  const newFilters = { ...filters };
                  newFilters.customer = e.target.value;
                  setFilters(newFilters);
                }}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">상태</label>
              <select
                className="px-2 py-1 border rounded-md text-sm w-full"
                onChange={(e) => {
                  const newFilters = { ...filters };
                  newFilters.status = e.target.value || null;
                  setFilters(newFilters);
                }}
              >
                <option value="">전체</option>
                <option value="completed">완료</option>
                <option value="pending">진행중</option>
                <option value="failed">실패</option>
              </select>
            </div>
          </div>
          <div className="mt-3 flex justify-end space-x-2">
            <button
              onClick={() => setFilters({})}
              className="px-3 py-1 border border-gray-300 rounded-md text-sm"
            >
              초기화
            </button>
            <button
              onClick={() => setFilterOpen(false)}
              className="px-3 py-1 bg-blue-600 text-white rounded-md text-sm"
            >
              적용
            </button>
          </div>
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full border-collapse">
          <thead className="bg-gray-100 sticky top-0">
            {table.getHeaderGroups().map(headerGroup => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map(header => (
                  <th key={header.id} className="p-3 text-left text-sm font-medium text-gray-700">
                    {header.isPlaceholder ? null : header.renderHeader()}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {isLoading ? (
              // 스켈레톤 로딩 UI
              Array.from({ length: 5 }).map((_, index) => (
                <tr key={`skeleton-${index}`} className="border-b animate-pulse">
                  {Array.from({ length: columns.length }).map((_, colIndex) => (
                    <td key={`skeleton-cell-${colIndex}`} className="p-3">
                      <div className="h-4 bg-gray-200 rounded"></div>
                    </td>
                  ))}
                </tr>
              ))
            ) : table.getRowModel().rows.length > 0 ? (
              table.getRowModel().rows.map(row => (
                <tr 
                  key={row.id} 
                  className="border-b hover:bg-gray-50 cursor-pointer"
                  onClick={() => onRowClick(row.original)}
                >
                  {row.getVisibleCells().map(cell => (
                    <td key={cell.id} className="p-3 text-sm">
                      {cell.renderCell()}
                    </td>
                  ))}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={columns.length} className="p-3 text-center text-gray-500">
                  데이터가 없습니다.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
