대량의 데이터를 효율적으로 탐색할 수 있는 페이지네이션 기능을 구현합니다. 서버 사이드 페이지네이션과 클라이언트 사이드 페이지네이션을 모두 지원하며, 무한 스크롤 옵션도 제공합니다.

```tsx
// hooks/useWorkRecordsPagination.ts
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabaseClient';
import { WorkRecord } from '../types/workRecord';

interface UseWorkRecordsPaginationProps {
  pageSize?: number;
  initialPage?: number;
  filters?: Record<string, any>;
  sortBy?: { column: string; direction: 'asc' | 'desc' };
}

export const useWorkRecordsPagination = ({
  pageSize = 10,
  initialPage = 0,
  filters = {},
  sortBy,
}: UseWorkRecordsPaginationProps = {}) => {
  const [page, setPage] = useState(initialPage);

  const buildQuery = () => {
    let query = supabase
      .from('work_records')
      .select('*', { count: 'exact' });

    // 필터 적용
    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        if (key === 'created_at' && value.start && value.end) {
          query = query.gte('created_at', value.start).lte('created_at', value.end);
        } else if (key === 'customer' || key === 'equipment') {
          query = query.ilike(key, `%${value}%`);
        } else {
          query = query.eq(key, value);
        }
      }
    });

    // 정렬 적용
    if (sortBy) {
      query = query.order(sortBy.column, { ascending: sortBy.direction === 'asc' });
    } else {
      query = query.order('created_at', { ascending: false });
    }

    // 페이지네이션 적용
    query = query.range(page * pageSize, (page + 1) * pageSize - 1);

    return query;
  };

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ['workRecords', page, pageSize, filters, sortBy],
    queryFn: async () => {
      const query = buildQuery();
      const { data, error, count } = await query;

      if (error) throw error;
      return { records: data as WorkRecord[], totalCount: count || 0 };
    },
    keepPreviousData: true,
  });

  const totalPages = data?.totalCount ? Math.ceil(data.totalCount / pageSize) : 0;

  const goToPage = (newPage: number) => {
    if (newPage >= 0 && newPage < totalPages) {
      setPage(newPage);
    }
  };

  const nextPage = () => {
    if (page < totalPages - 1) {
      setPage(page + 1);
    }
  };

  const prevPage = () => {
    if (page > 0) {
      setPage(page - 1);
    }
  };

  return {
    records: data?.records || [],
    totalCount: data?.totalCount || 0,
    totalPages,
    currentPage: page,
    isLoading,
    error,
    goToPage,
    nextPage,
    prevPage,
    refetch,
  };
};

// components/TablePagination/index.tsx
interface TablePaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
}

const TablePagination = ({ currentPage, totalPages, onPageChange }: TablePaginationProps) => {
  // 페이지 번호 배열 생성 (현재 페이지 주변 5개 페이지 표시)
  const getPageNumbers = () => {
    const pageNumbers = [];
    const maxPagesToShow = 5;
    const startPage = Math.max(0, currentPage - Math.floor(maxPagesToShow / 2));
    const endPage = Math.min(totalPages - 1, startPage + maxPagesToShow - 1);

    for (let i = startPage; i <= endPage; i++) {
      pageNumbers.push(i);
    }

    return pageNumbers;
  };

  if (totalPages <= 1) return null;

  return (
    <div className="flex items-center justify-center space-x-1 mt-4">
      <button
        onClick={() => onPageChange(0)}
        disabled={currentPage === 0}
        className="px-2 py-1 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed"
      >
        처음
      </button>
      <button
        onClick={() => onPageChange(currentPage - 1)}
        disabled={currentPage === 0}
        className="px-2 py-1 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed"
      >
        이전
      </button>

      {getPageNumbers().map(pageNumber => (
        <button
          key={pageNumber}
          onClick={() => onPageChange(pageNumber)}
          className={`px-3 py-1 rounded-md text-sm ${
            currentPage === pageNumber
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 hover:bg-gray-200'
          }`}
        >
          {pageNumber + 1}
        </button>
      ))}

      <button
        onClick={() => onPageChange(currentPage + 1)}
        disabled={currentPage === totalPages - 1}
        className="px-2 py-1 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed"
      >
        다음
      </button>
      <button
        onClick={() => onPageChange(totalPages - 1)}
        disabled={currentPage === totalPages - 1}
        className="px-2 py-1 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed"
      >
        마지막
      </button>
    </div>
  );
};
