import { useInfiniteQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabaseClient';
import { WorkRecord } from '../types/workRecord';

interface UseInfiniteWorkRecordsProps {
  pageSize?: number;
  filters?: Record<string, any>;
  sortBy?: { column: string; direction: 'asc' | 'desc' };
}

export const useInfiniteWorkRecords = ({
  pageSize = 10,
  filters = {},
  sortBy,
}: UseInfiniteWorkRecordsProps = {}) => {
  const buildQuery = (page: number) => {
    let query = supabase
      .from('work_records')
      .select('*', { count: 'exact' });

    // 필터 적용
    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        if (key === 'created_at' && value.start && value.end) {
          query = query.gte('created_at', value.start).lte('created_at', value.end);
        } else if (key === 'customer' || key === 'equipment') {
          query = query.ilike(key, `%${value}%`);
        } else {
          query = query.eq(key, value);
        }
      }
    });

    // 정렬 적용
    if (sortBy) {
      query = query.order(sortBy.column, { ascending: sortBy.direction === 'asc' });
    } else {
      query = query.order('created_at', { ascending: false });
    }

    // 페이지네이션 적용
    query = query.range(page * pageSize, (page + 1) * pageSize - 1);

    return query;
  };

  return useInfiniteQuery({
    queryKey: ['infiniteWorkRecords', pageSize, filters, sortBy],
    queryFn: async ({ pageParam = 0 }) => {
      const query = buildQuery(pageParam);
      const { data, error, count } = await query;

      if (error) throw error;
      return { 
        records: data as WorkRecord[], 
        totalCount: count || 0,
        nextPage: data.length === pageSize ? pageParam + 1 : undefined 
      };
    },
    getNextPageParam: (lastPage) => lastPage.nextPage,
    getPreviousPageParam: (_, allPages) => allPages.length - 1,
    refetchOnWindowFocus: false,
    staleTime: 5 * 60 * 1000, // 5분 캐싱
  });
};

// components/InfiniteScrollTable/index.tsx
import { useRef, useCallback } from 'react';
import { useInfiniteWorkRecords } from '../../hooks/useInfiniteWorkRecords';
import { SkeletonLoader } from '../SkeletonLoader';

const InfiniteScrollTable = () => {
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isLoading } = useInfiniteWorkRecords();

  const observer = useRef<IntersectionObserver | null>(null);
  const lastRowRef = useCallback(
    (node: HTMLElement | null) => {
      if (isFetchingNextPage) return;
      if (observer.current) observer.current.disconnect();

      observer.current = new IntersectionObserver(entries => {
        if (entries[0].isIntersecting && hasNextPage) {
          fetchNextPage();
        }
      });

      if (node) observer.current.observe(node);
    },
    [isFetchingNextPage, fetchNextPage, hasNextPage]
  );

  const allRecords = data?.pages.flatMap(page => page.records) || [];

  return (
    <div className="overflow-x-auto">
      <table className="w-full border-collapse">
        <thead className="bg-gray-100 sticky top-0">
          <tr>
            <th className="p-3 text-left">작업일</th>
            <th className="p-3 text-left">고객/장비</th>
            <th className="p-3 text-left">ECU 정보</th>
            <th className="p-3 text-left">ACU 정보</th>
            <th className="p-3 text-left">상태</th>
            <th className="p-3 text-left">금액</th>
            <th className="p-3 text-left">작업</th>
          </tr>
        </thead>
        <tbody>
          {isLoading ? (
            <tr>
              <td colSpan={7}>
                <SkeletonLoader />
              </td>
            </tr>
          ) : allRecords.length > 0 ? (
            allRecords.map((record, index) => (
              <tr 
                key={record.id} 
                className="border-b hover:bg-gray-50 cursor-pointer"
                ref={index === allRecords.length - 1 ? lastRowRef : null}
              >
                <td className="p-3">{new Date(record.created_at).toLocaleDateString('ko-KR')}</td>
                <td className="p-3">{record.customer} / {record.equipment}</td>
                <td className="p-3 text-blue-600">{record.ecu_info.model} ({record.ecu_info.serial})</td>
                <td className="p-3 text-green-600">{record.acu_info ? `${record.acu_info.model} (${record.acu_info.serial})` : '-'}</td>
                <td className="p-3">
                  <span className={`px-2 py-1 rounded-full text-xs ${getStatusColor(record.status)}`}>
                    {getStatusText(record.status)}
                  </span>
                </td>
                <td className="p-3">{new Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'KRW' }).format(record.amount)}</td>
                <td className="p-3">
                  <button className="text-blue-500 hover:text-blue-700">상세보기</button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan={7} className="p-3 text-center text-gray-500">
                데이터가 없습니다.
              </td>
            </tr>
          )}
          {isFetchingNextPage && (
            <tr>
              <td colSpan={7}>
                <SkeletonLoader rows={3} />
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};
