```tsx
// components/AccessibleTable/index.tsx
import { useRef, useEffect, KeyboardEvent } from 'react';
import { WorkRecord } from '../../types/workRecord';

interface AccessibleTableProps {
  data: WorkRecord[];
  isLoading: boolean;
  onRowClick: (record: WorkRecord) => void;
}

const AccessibleTable = ({ data, isLoading, onRowClick }: AccessibleTableProps) => {
  const tableRef = useRef<HTMLTableElement>(null);

  // 키보드 탐색 처리
  const handleKeyDown = (e: KeyboardEvent<HTMLTableRowElement>, record: WorkRecord) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onRowClick(record);
    }
  };

  // 포커스 관리
  useEffect(() => {
    const handleTabKey = (e: KeyboardEvent) => {
      if (e.key === 'Tab' && tableRef.current) {
        const rows = tableRef.current.querySelectorAll('tbody tr');
        const focusedElement = document.activeElement;

        // 테이블 내부에 포커스가 있는지 확인
        let isInsideTable = false;
        rows.forEach(row => {
          if (row.contains(focusedElement)) {
            isInsideTable = true;
          }
        });

        // 테이블 내부에 포커스가 없으면 첫 번째 행에 포커스
        if (!isInsideTable && rows.length > 0) {
          (rows[0] as HTMLElement).focus();
        }
      }
    };

    document.addEventListener('keydown', handleTabKey as any);
    return () => document.removeEventListener('keydown', handleTabKey as any);
  }, []);

  return (
    <div className="overflow-x-auto" role="region" aria-label="작업 이력 테이블">
      <table ref={tableRef} className="w-full border-collapse" aria-busy={isLoading}>
        <caption className="sr-only">작업 이력 목록</caption>
        <thead className="bg-gray-100 sticky top-0">
          <tr>
            <th scope="col" className="p-3 text-left">작업일</th>
            <th scope="col" className="p-3 text-left">고객/장비</th>
            <th scope="col" className="p-3 text-left">ECU 정보</th>
            <th scope="col" className="p-3 text-left">ACU 정보</th>
            <th scope="col" className="p-3 text-left">상태</th>
            <th scope="col" className="p-3 text-left">금액</th>
            <th scope="col" className="p-3 text-left">작업</th>
          </tr>
        </thead>
        <tbody>
          {isLoading ? (
            <tr>
              <td colSpan={7} className="p-3 text-center">
                <div className="sr-only">데이터 로딩 중...</div>
                <div className="animate-pulse space-y-3">
                  {Array.from({ length: 5 }).map((_, index) => (
                    <div key={index} className="h-10 bg-gray-200 rounded"></div>
                  ))}
                </div>
              </td>
            </tr>
          ) : data.length > 0 ? (
            data.map(record => (
              <tr 
                key={record.id} 
                className="border-b hover:bg-gray-50 cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-blue-50"
                onClick={() => onRowClick(record)}
                onKeyDown={(e) => handleKeyDown(e, record)}
                tabIndex={0}
                role="button"
                aria-label={`${record.customer} ${record.equipment} 작업 정보, ${new Date(record.created_at).toLocaleDateString('ko-KR')}`}
              >
                <td className="p-3">{new Date(record.created_at).toLocaleDateString('ko-KR')}</td>
                <td className="p-3">{record.customer} / {record.equipment}</td>
                <td className="p-3 text-blue-600">
                  <span aria-label={`ECU 모델: ${record.ecu_info.model}, 시리얼: ${record.ecu_info.serial}`}>
                    {record.ecu_info.model} ({record.ecu_info.serial})
                  </span>
                </td>
                <td className="p-3 text-green-600">
                  {record.acu_info ? (
                    <span aria-label={`ACU 모델: ${record.acu_info.model}, 시리얼: ${record.acu_info.serial}`}>
                      {record.acu_info.model} ({record.acu_info.serial})
                    </span>
                  ) : (
                    <span aria-label="ACU 정보 없음">-</span>
                  )}
                </td>
                <td className="p-3">
                  <span 
                    className={`px-2 py-1 rounded-full text-xs ${getStatusColor(record.status)}`}
                    aria-label={`상태: ${getStatusText(record.status)}`}
                  >
                    {getStatusText(record.status)}
                  </span>
                </td>
                <td className="p-3" aria-label={`금액: ${new Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'KRW' }).format(record.amount)}`}>
                  {new Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'KRW' }).format(record.amount)}
                </td>
                <td className="p-3">
                  <button 
                    className="text-blue-500 hover:text-blue-700 focus:outline-none focus:underline"
                    aria-label={`${record.customer} ${record.equipment} 상세 정보 보기`}
                    onClick={(e) => {
                      e.stopPropagation();
                      onRowClick(record);
                    }}
                  >
                    상세보기
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan={7} className="p-3 text-center text-gray-500">
                데이터가 없습니다.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

// utils/accessibilityUtils.ts
export const getStatusColor = (status: string) => {
  switch (status) {
    case 'completed':
      return 'bg-green-100 text-green-800';
    case 'pending':
      return 'bg-yellow-100 text-yellow-800';
    case 'failed':
      return 'bg-red-100 text-red-800';
    default:
      return 'bg-gray-100 text-gray-800';
  }
};

export const getStatusText = (status: string) => {
  switch (status) {
    case 'completed':
      return '완료';
    case 'pending':
      return '진행중';
    case 'failed':
      return '실패';
    default:
      return '알 수 없음';
  }
};
