```tsx
// pages/work-records.tsx
import { useState } from 'react';
import { NextPage } from 'next';
import Head from 'next/head';
import { WorkRecordTable } from '../components/WorkRecordTable';
import { WorkDetailModal } from '../components/WorkDetailModal';
import { TablePagination } from '../components/TablePagination';
import { useWorkRecordsPagination } from '../hooks/useWorkRecordsPagination';
import { WorkRecord } from '../types/workRecord';

const WorkRecordsPage: NextPage = () => {
  const [selectedRecord, setSelectedRecord] = useState<WorkRecord | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [filters, setFilters] = useState<Record<string, any>>({});
  const [sortBy, setSortBy] = useState<{ column: string; direction: 'asc' | 'desc' } | undefined>();

  const { 
    records, 
    totalCount, 
    totalPages, 
    currentPage, 
    isLoading, 
    error, 
    goToPage, 
    refetch 
  } = useWorkRecordsPagination({
    pageSize: 10,
    filters,
    sortBy,
  });

  const handleRowClick = (record: WorkRecord) => {
    setSelectedRecord(record);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const handleFilterChange = (newFilters: Record<string, any>) => {
    setFilters(newFilters);
  };

  const handleSortChange = (column: string, direction: 'asc' | 'desc') => {
    setSortBy({ column, direction });
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <Head>
        <title>작업 이력 | ECU Manager</title>
        <meta name="description" content="ECU Manager 시스템의 작업 이력 페이지입니다." />
      </Head>

      <h1 className="text-2xl font-bold mb-6">작업 이력</h1>

      {error && (
        <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 mb-4" role="alert">
          <p className="font-bold">오류 발생</p>
          <p>{error instanceof Error ? error.message : '데이터를 불러오는 중 오류가 발생했습니다.'}</p>
        </div>
      )}

      <WorkRecordTable 
        data={records} 
        isLoading={isLoading} 
        onRowClick={handleRowClick}
        onFilterChange={handleFilterChange}
        onSortChange={handleSortChange}
      />

      <div className="mt-4">
        <p className="text-sm text-gray-500 mb-2">총 {totalCount}개의 작업 이력</p>
        <TablePagination 
          currentPage={currentPage} 
          totalPages={totalPages} 
          onPageChange={goToPage} 
        />
      </div>

      <WorkDetailModal 
        isOpen={isModalOpen} 
        onClose={handleCloseModal} 
        workRecord={selectedRecord} 
      />
    </div>
  );
};

export default WorkRecordsPage;

